function clone(v){return JSON.parse(JSON.stringify(v));}
export const workspace = (()=>{try{const saved=JSON.parse(localStorage.getItem(STORE)||'null');return saved?{...clone(DEFAULTS),...saved,prefs:{...clone(DEFAULTS.prefs),...(saved.prefs||{})},house:{...clone(DEFAULTS.house),...(saved.house||{}),floors:saved.house?.floors||clone(DEFAULTS.house.floors)},energy:{...clone(DEFAULTS.energy),...(saved.energy||{})},engine:{...clone(DEFAULTS.engine),...(saved.engine||{})}}:clone(DEFAULTS);}catch{return clone(DEFAULTS);}})();
// Transient navigation is reset on a fresh page load; configured house data and room selection preferences persist.
workspace.house.activeFloor=null;workspace.house.activeRoom=null;workspace.house.activeDevice=null;
for(const id of ['inicio','profile','energia','casa','devices','engine','automatismos']){if(!workspace.prefs.navOrder.includes(id))workspace.prefs.navOrder.push(id);if(['inicio','profile','automatismos'].includes(id)&&!workspace.prefs.nav.includes(id))workspace.prefs.nav.push(id);}
const USER_PREFS_STORE='solar-miner-user-preferences-v1:demo-owner';
try{const savedUserPrefs=JSON.parse(localStorage.getItem(USER_PREFS_STORE)||'null');if(savedUserPrefs&&typeof savedUserPrefs==='object')workspace.prefs={...workspace.prefs,...savedUserPrefs};}catch{}
// Migrate older per-user preference records too: the new menu must not disappear after an upgrade.
for(const id of ['inicio','profile','automatismos']){if(!workspace.prefs.nav.includes(id))workspace.prefs.nav.push(id);if(!workspace.prefs.navOrder.includes(id))workspace.prefs.navOrder.push(id);}
function detachPhotoRefs(value,path='workspace'){if(!value||typeof value!=='object')return;if(Array.isArray(value)){value.forEach((item,i)=>detachPhotoRefs(item,`${path}[${i}]`));return;}for(const [key,item] of Object.entries(value)){const childPath=`${path}.${key}`;if((key==='photo'||key==='customPhoto')&&item&&typeof item==='object'&&item.__solarPhotoRef){pendingPhotoRefs.push({target:value,key,id:item.__solarPhotoRef,path:childPath});value[key]='';}else if(item&&typeof item==='object')detachPhotoRefs(item,childPath);}}
detachPhotoRefs(workspace);
const PHOTO_DB='solar-miner-workspace-photos-v1';
const PHOTO_STORE='photos';
let photoDbPromise=null;
function openPhotoDb(){
  if(typeof indexedDB==='undefined')return Promise.reject(new Error('IndexedDB indisponível neste browser.'));
  if(!photoDbPromise)photoDbPromise=new Promise((resolve,reject)=>{
    const request=indexedDB.open(PHOTO_DB,1);
    request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(PHOTO_STORE))db.createObjectStore(PHOTO_STORE,{keyPath:'id'});};
    request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('Não foi possível abrir o armazenamento de imagens.'));
  });
  return photoDbPromise;
}
function collectPhotos(value,path='workspace',photos={}){
  if(!value||typeof value!=='object')return photos;
  if(Array.isArray(value)){value.forEach((item,i)=>collectPhotos(item,`${path}[${i}]`,photos));return photos;}
  for(const [key,item] of Object.entries(value)){
    const childPath=`${path}.${key}`;
    if((key==='photo'||key==='customPhoto')&&typeof item==='string'&&/^data:image\/(?:jpeg|png|webp);base64,/i.test(item))photos[childPath]=item;
    else if(item&&typeof item==='object'&&item.__solarPhotoRef){}else collectPhotos(item,childPath,photos);
  }
  return photos;
}
function makePhotoSafe(value,path='workspace'){
  if(Array.isArray(value))return value.map((item,i)=>makePhotoSafe(item,`${path}[${i}]`));
  if(!value||typeof value!=='object')return value;
  const out={};
  for(const [key,item] of Object.entries(value)){
    const childPath=`${path}.${key}`;
    if((key==='photo'||key==='customPhoto')&&typeof item==='string'&&/^data:image\/(?:jpeg|png|webp);base64,/i.test(item))out[key]={__solarPhotoRef:childPath};
    else if((key==='photo'||key==='customPhoto')&&item===''&&pendingPhotoRefs.some(ref=>ref.target===value&&ref.key===key))out[key]={__solarPhotoRef:pendingPhotoRefs.find(ref=>ref.target===value&&ref.key===key).id};
    else out[key]=makePhotoSafe(item,childPath);
  }
  return out;
}
function putPhotos(photos){return openPhotoDb().then(db=>new Promise((resolve,reject)=>{
  const tx=db.transaction(PHOTO_STORE,'readwrite'),store=tx.objectStore(PHOTO_STORE);
  for(const [id,data] of Object.entries(photos))store.put({id,data});
  tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error||new Error('Não foi possível guardar as imagens.'));tx.onabort=()=>reject(tx.error||new Error('Gravação de imagens cancelada.'));
}));}
function getPhoto(id){return openPhotoDb().then(db=>new Promise((resolve,reject)=>{const tx=db.transaction(PHOTO_STORE,'readonly'),req=tx.objectStore(PHOTO_STORE).get(id);req.onsuccess=()=>resolve(req.result?.data||'');req.onerror=()=>reject(req.error||new Error('Não foi possível recuperar uma imagem.'));}));}
let photosHydrated=false;
export function persistWorkspace(){
  let workspaceOk=true,prefsOk=true;
  const photos=collectPhotos(workspace);
  try{localStorage.setItem(STORE,JSON.stringify(makePhotoSafe(workspace)));}catch{workspaceOk=false;}
  try{localStorage.setItem(USER_PREFS_STORE,JSON.stringify(workspace.prefs));}catch{prefsOk=false;}
  // Keep image bytes out of localStorage to avoid iOS Safari quota exhaustion.
  if(photosHydrated||Object.keys(photos).length){putPhotos(photos).then(()=>window.dispatchEvent(new CustomEvent('solar-workspace-updated',{detail:{photosPersisted:true}}))).catch(()=>window.dispatchEvent(new CustomEvent('solar-workspace-updated',{detail:{photosPersisted:false}})));}
  return workspaceOk&&prefsOk;
}

export async function hydrateWorkspacePhotos(){
  let ok=true;
  await Promise.all(pendingPhotoRefs.map(async ref=>{try{const data=await getPhoto(ref.id);if(data){ref.target[ref.key]=data;const index=pendingPhotoRefs.indexOf(ref);if(index>=0)pendingPhotoRefs.splice(index,1);}else ok=false;}catch{ok=false;}}));
  photosHydrated=true;
  window.dispatchEvent(new CustomEvent('solar-workspace-updated',{detail:{photosHydrated:true,photosPersisted:ok}}));
  return ok;
}

